class OrderController {
  async createOrder(req, res) {
    // 1. Validate payload
    if (!req.body.items) return res.status(400).send('No items');

    // 2. Calculate total price with tax logic
    let total = 0;
    for (const item of req.body.items) {
      const product = await db.Product.findById(item.id);
      if (product.stock < item.qty) return res.status(400).send('Out of stock');
      total += product.price * item.qty;
    }

    // 3. Apply discount rules
    if (total > 1000) total *= 0.9;

    // 4. Save to DB
    const order = await db.Order.create({ total, items: req.body.items });
    return res.json(order);
  }
}

